    'admin_shadow-saas-grip.abort_failed_prefix' => 'Falha ao cancelar a sincronização: ',
    'admin_shadow-saas-grip.abort_grip_confirm' => 'Cancelar a sincronização do Grip em execução?',
    'admin_shadow-saas-grip.abort_hero_confirm' => 'Cancelar a sincronização do HERO em execução?',
    'admin_shadow-saas-grip.about_grip_body' => 'O Grip Security descobre e monitoriza continuamente aplicações SaaS-of-Record em todo o seu ambiente.
Esta integração:<br><br>
<strong>&bull; Espelha os dados do Grip:</strong> Extrai o inventário completo de SaaS / utilizadores / alertas para as tabelas <code>shadow_saas_grip_*</code>.<br>
<strong>&bull; Hidrata o Shadow SaaS:</strong> Projeta cada aplicação SaaS na lista Shadow SaaS existente, normalizando o URL para o seu domínio registável, de modo que a correspondência de fornecedores funcione da mesma forma que uma importação por CSV.<br>
<strong>&bull; Acompanha o risco:</strong> Persiste a pontuação de risco do Grip, a etiqueta de sanção, as contagens de âmbitos OAuth, a classificação de profundidade de IA, o suporte a MFA / SAML e os metadados de contacto principal.<br>
<strong>&bull; Mantém-se atualizada:</strong> Volta a executar segundo a agenda cron configurada; os administradores também podem acionar uma execução imediata em segundo plano com o botão "Run Now" acima.',
    'admin_shadow-saas-grip.about_grip_heading' => 'Sobre a Integração com o Grip',
    'admin_shadow-saas-grip.about_hero_body' => 'O HERO Security descobre fornecedores SaaS de terceiros e os problemas que os afetam em todo o seu ambiente.
Esta integração:<br><br>
<strong>&bull; Espelha os dados do HERO:</strong> Extrai fornecedores / problemas / utilizadores por fornecedor para as tabelas <code>shadow_saas_hero_*</code>.<br>
<strong>&bull; Hidrata o Shadow SaaS:</strong> Projeta cada fornecedor na lista Shadow SaaS existente por domínio registável, de modo que a correspondência funcione da mesma forma que uma importação por CSV.<br>
<strong>&bull; Acompanha o risco:</strong> Deriva uma pontuação de risco de 1-5 a partir do pior problema aberto por fornecedor (a mesma escala de 1-5 que o Grip usa) e regista o estado do fornecedor e os aspetos de envolvimento.<br>
<strong>&bull; Mantém-se atualizada:</strong> Volta a executar no trabalho partilhado de Re-hidratação Agendada; os administradores também podem acionar uma execução imediata com o botão "Run Now" abaixo.',
    'admin_shadow-saas-grip.about_hero_heading' => 'Sobre a Integração com o HERO',
    'admin_shadow-saas-grip.api_key_label' => 'Chave da API',
    'admin_shadow-saas-grip.api_reference_heading' => 'Referência da API',
    'admin_shadow-saas-grip.api_token_help' => 'Enviado como o cabeçalho HTTP <code>access-token</code> em cada pedido. Deixe em branco para manter o token existente.',
    'admin_shadow-saas-grip.api_token_label' => 'Token da API',
    'admin_shadow-saas-grip.api_url_host_not_allowed' => 'O anfitrião do URL da API não é permitido.',
    'admin_shadow-saas-grip.api_url_invalid' => 'O URL da API tem de ser um URL http(s) válido.',
    'admin_shadow-saas-grip.api_url_label' => 'URL da API',
    'admin_shadow-saas-grip.apps_with_users_suffix' => ' aplicações com utilizadores',
    'admin_shadow-saas-grip.client_id_label' => 'Client ID',
    'admin_shadow-saas-grip.client_secret_label' => 'Client Secret',
    'admin_shadow-saas-grip.currently_holding_prefix' => 'Atualmente com ',
    'admin_shadow-saas-grip.data_source_help' => '<strong>Em direto</strong> chama a API do Grip em cada página (sempre atual, mais pesado para a API). <strong>Local (Hidratado/em cache)</strong> serve as tabelas hidratadas <code>shadow_saas_grip_*</code> na base de dados - mais leve para a API - e um instantâneo por aplicação em falta é obtido da API uma vez e depois colocado em cache. No modo Local, cada sincronização <strong>atualiza totalmente</strong> os dados: as tabelas de espelho do Grip são truncadas e re-hidratadas a partir da API.',
    'admin_shadow-saas-grip.data_source_label' => 'Fonte de dados',
    'admin_shadow-saas-grip.data_source_live' => 'Em direto - consultar a API do Grip em cada visualização',
    'admin_shadow-saas-grip.data_source_local' => 'Local (Hidratado/em cache) - servir a partir da base de dados',
    'admin_shadow-saas-grip.download_postman_json' => 'Descarregar Postman (JSON)',
    'admin_shadow-saas-grip.download_swagger_yaml' => 'Descarregar Swagger (YAML)',
    'admin_shadow-saas-grip.enable_grip' => 'Ativar a integração com o Grip Security',
    'admin_shadow-saas-grip.enable_hero' => 'Ativar a integração com o HERO Security',
    'admin_shadow-saas-grip.enable_scheduled_rehydration' => 'Ativar re-hidratação agendada',
    'admin_shadow-saas-grip.enable_zscaler' => 'Ativar bloqueio por Categoria de URL do Zscaler ao Recusar',
    'admin_shadow-saas-grip.enter_admin_api_key' => 'Introduza a chave da API de administrador',
    'admin_shadow-saas-grip.failed_truncate_prefix' => 'Falha ao truncar ',
    'admin_shadow-saas-grip.flow_grip_breach_label' => 'Encaminhar informações de violação do Grip para Breach&nbsp;/&nbsp;Cyber Alerts',
    'admin_shadow-saas-grip.grip_all_cleared_p1' => 'Todos os dados do Grip foram eliminados: ',
    'admin_shadow-saas-grip.grip_all_cleared_p2' => ' tabela(s) de espelho truncada(s), ',
    'admin_shadow-saas-grip.grip_all_cleared_p3' => ' linha(s) do Shadow SaaS removida(s), e ',
    'admin_shadow-saas-grip.grip_all_cleared_p4' => ' registo(s) de fornecedor com telemetria do Grip removida.',
    'admin_shadow-saas-grip.grip_api_reference_intro' => 'Inventário de endpoints para a API pública do Grip Security (base do servidor <code>https://&lt;tenant&gt;.dep.grip.security/public</code>, OpenAPI 3.1 gerado automaticamente). A sincronização do FairTPRM consome os endpoints de leitura (GET) marcados como <em>usado pela sincronização</em>; o inventário completo &mdash; incluindo os grupos Users, Workflows, Posture&nbsp;Management, AuditLogs, Alerts / Alerts&nbsp;V2, Actions e AI&nbsp;Agents &mdash; encontra-se nos downloads OpenAPI e Postman abaixo. A extração de domínios normaliza os URLs para o respetivo domínio registável (por exemplo, <code>https://www.united.com</code> → <code>united.com</code>, <code>http://color.redhat.com</code> → <code>redhat.com</code>).',
    'admin_shadow-saas-grip.grip_auth_help' => 'Cabeçalho de autenticação: <code>access-token: &lt;your-token&gt;</code>. A variável <code>accessToken</code> da coleção Postman está definida como <code>REPLACE_ME</code>; substitua-a pelo token do seu tenant antes de enviar pedidos.',
    'admin_shadow-saas-grip.grip_base_url_help' => 'URL do Grip com prefixo do tenant enraizado em <code>/public/saas</code> (por exemplo, <code>https://tenant.dep.grip.security/public/saas</code>). Os endpoints irmãos (<code>/public/users</code>, <code>/public/alerts</code>) são derivados deste anfitrião.',
    'admin_shadow-saas-grip.grip_base_url_label' => 'Servidor (URL Base do Tenant)',
    'admin_shadow-saas-grip.grip_breach_help' => 'Em cada re-hidratação agendada (e no <strong>Run&nbsp;Now</strong> manual abaixo), os alertas "Security Incident Detected" do Grip são escritos no sistema <a href="breach-alerts.php">Breach&nbsp;/&nbsp;Cyber Alerts</a> (sem duplicados). As violações de um fornecedor integrado são associadas a esse fornecedor; as violações de uma aplicação sem fornecedor integrado são igualmente registadas e etiquetadas como <strong>Shadow&nbsp;SaaS</strong> com o número de utilizadores potencialmente afetados. Requer o Grip ativado (acima) <em>e</em> a definição Breach&nbsp;/&nbsp;Cyber Alert em <a href="admin.php?section=email">Email &amp; Alerts</a>.',
    'admin_shadow-saas-grip.grip_config_update_failed_prefix' => 'Falha ao atualizar a configuração do Grip: ',
