    'admin_shadow-saas-grip.hero_base_url_help' => 'Base da API pública do HERO, por exemplo, <code>https://api.herosecurity.ai/stable</code>. Os endpoints (<code>/v1/vendors</code>, <code>/v1/issues</code>) são derivados deste anfitrião.',
