    'admin_shadow-saas-grip.zscaler_intro' => 'Quando um fornecedor é recusado na lista Shadow SaaS, o domínio do fornecedor é acrescentado à Categoria de URL abaixo no Zscaler ZIA (usando <code>action=ADD_TO_LIST</code>) e depois ativado. Partilhado por ambos os fornecedores.',
