    'admin_shadow-saas-grip.zscaler_vanity_help' => 'Anfitrião do endpoint de token OAuth do tenant ZIdentity - o URL do token é <code>https://&lt;vanity&gt;/oauth2/v1/token</code>. Encontre-o no URL de administração do ZIdentity (a parte antes de <code>.zslogin.net</code>).',
    'admin_shadow-saas-grip.zscaler_vanity_label' => 'Domínio Personalizado ZIdentity',
    'admin_shodan-srs.about_body' => 'O Shodan é uma plataforma de inteligência da Internet que analisa e indexa todos os dispositivos ligados à Internet que consegue encontrar. A integração permite:<br><br><strong>• Análise de Portas:</strong> Identificar portas abertas na infraestrutura do fornecedor, incluindo serviços de alto risco (FTP, Telnet, RDP, SMB)<br><strong>• Deteção de Vulnerabilidades:</strong> Descobrir CVEs conhecidos associados aos endereços IP e serviços do fornecedor<br><strong>• Identificação de Serviços:</strong> Catalogar serviços em execução, versões de software e configurações de servidor<br><strong>• Pontuação de Segurança:</strong> Gerar uma pontuação de segurança de 0-100 com base na superfície de ataque exposta',
    'admin_shodan-srs.about_heading' => 'Acerca do Shodan',
    'admin_shodan-srs.about_learn_more' => 'Saber mais sobre o Shodan →',
    'admin_shodan-srs.about_note_body' => 'As pontuações do Shodan são complementares às pontuações do UpGuard. O UpGuard foca-se na postura de segurança global (escala de 0-950), enquanto o Shodan se foca na infraestrutura exposta (escala de 0-100). Ambos podem ser ativados em simultâneo para avaliações abrangentes de fornecedores.',
    'admin_shodan-srs.about_note_label' => 'Nota:',
    'admin_shodan-srs.across' => 'em',
    'admin_shodan-srs.active_waiver_singular' => 'dispensa ativa',
    'admin_shodan-srs.active_waivers_plural' => 'dispensas ativas',
    'admin_shodan-srs.api_key_help' => 'Chave da API da sua <a href="https://account.shodan.io" target="_blank">conta Shodan</a>. Deixe em branco para manter a chave existente.',
    'admin_shodan-srs.api_key_label' => 'Chave da API do Shodan',
    'admin_shodan-srs.api_key_placeholder' => 'Introduza a chave da API',
    'admin_shodan-srs.banner_max_age_help' => 'Ignorar dados de banner do Shodan mais antigos do que este número de dias. O Shodan retém dados históricos de portas que podem estar agora filtradas/fechadas. Defina 0 para desativar a filtragem por atualidade. Predefinição: 7 dias.',
    'admin_shodan-srs.banner_max_age_label' => 'Idade Máxima do Banner (Dias)',
