    'admin_shodan-srs.min_cve_year_help_suffix' => '). A deteção do Shodan baseada em banners corresponde frequentemente CVEs muito antigos a cadeias de versão de software, produzindo falsos positivos. Defina um ano específico para substituir, ou deixe em 0 para utilizar a janela móvel de 5 anos.',
