    'admin_shodan-srs.on_demand_help' => 'Quando ativado, o Shodan solicitará uma análise a pedido para quaisquer IPs sobre os quais não tenha dados existentes durante a pontuação. Isto garante cobertura para domínios que o Shodan não analisou anteriormente, mas utiliza créditos de análise (1 crédito por IP) e acrescenta até 3 minutos de tempo de espera por pedido de pontuação enquanto o Shodan processa a análise. Recomendado para fornecedores relativamente aos quais o Shodan não devolve sinais de segurança.',
    'admin_shodan-srs.on_demand_label' => 'Ativar Análise a Pedido',
