    'admin_shodan-srs.word_waiver' => 'dispensa',
    'admin_shodan-srs.word_waivers' => 'dispensas',
    'admin_srs.about_custom_body' => 'A pontuação personalizada permite-lhe introduzir manualmente pontuações de segurança para fornecedores utilizando ferramentas de avaliação externas ou serviços de classificação.<br><br><strong>Intervalo de Pontuação:</strong> 1-100 (escala percentual)<br><strong>Classificação:</strong> A &ge; 90, B &ge; 75, C &ge; 60, D &ge; 40, F &lt; 40<br><br>Quando existem várias fontes de pontuação (UpGuard, Shodan, Personalizada), é calculada e apresentada em toda a aplicação uma pontuação média combinada. Isto proporciona uma visão unificada da postura de segurança de cada fornecedor a partir de todas as fontes disponíveis.',
    'admin_srs.about_custom_heading' => 'Acerca da Pontuação Personalizada',
    'admin_srs.about_upguard_body' => 'O UpGuard CyberRisk fornece classificações de segurança automatizadas e monitorização contínua para fornecedores terceiros. A integração permite:<br><br><strong>• Pontuação de Segurança Automatizada:</strong> Obtenha classificações de segurança instantâneas (0-950) para fornecedores com base na sua postura de segurança externa<br><strong>• Identificação de Riscos:</strong> Identifique automaticamente riscos de segurança de gravidade alta, média e baixa<br><strong>• Análise de Tendências:</strong> Acompanhe as pontuações de segurança dos fornecedores ao longo do tempo para identificar melhorias ou degradações<br><strong>• Monitorização Baseada em Níveis:</strong> Configure a frequência de recálculo com base na criticidade do fornecedor',
    'admin_srs.about_upguard_heading' => 'Acerca do UpGuard CyberRisk',
    'admin_srs.about_upguard_learn_more' => 'Saber mais sobre o UpGuard CyberRisk &rarr;',
