    'admin_srs.cron_lock_files_note' => 'Utiliza ficheiros de bloqueio para evitar execuções sobrepostas. Consulte o <span data-action="openCronInfoModal" style="color: var(--theme-header-color, #2563eb); cursor: pointer; text-decoration: underline;">Guia de Configuração do Cron</span> para obter detalhes.',
    'admin_srs.cron_modal_heading' => 'Configuração da Tarefa Cron para o Recálculo do SRS',
    'admin_srs.cron_note_body' => 'O histórico de execução é registado na base de dados. Consulte Admin &gt; SRS para ver execuções anteriores e eventuais erros.',
    'admin_srs.cron_ondemand_desc' => 'Processa os pedidos de recálculo manuais colocados em fila a partir da página de detalhes do fornecedor. <strong>Necessário</strong> quando "Utilizar Cron para o Recálculo" está ativado em qualquer uma das integrações:',
    'admin_srs.cron_ondemand_heading' => '2. Fila de Recálculo a Pedido <span style="background: #dbeafe; color: #1e40af; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 600; vertical-align: middle;">Necessária para "Utilizar Cron"</span>',
    'admin_srs.cron_ondemand_note' => 'Executa a cada minuto. Utiliza ficheiros de bloqueio para evitar execuções sobrepostas. Processa apenas um fornecedor de cada vez para evitar os limites de taxa da API. Se não existirem recálculos pendentes, a tarefa termina imediatamente.',
    'admin_srs.cron_prereq_enabled' => 'Certifique-se de que pelo menos uma integração SRS está ativada com uma chave da API válida',
